<div class="admin-page-head"><h1>سفارش‌ها</h1></div><section class="panel"><?php $status=AdminTables::orderStatus();$params=$_GET;$params["Grid"]=isset($params["Grid"])&&is_array($params["Grid"])?$params["Grid"]:array();$params["Grid"]["orders"]=isset($params["Grid"]["orders"])&&is_array($params["Grid"]["orders"])?$params["Grid"]["orders"]:array();unset($params['status'],$params['orders_page']);if(isset($params['Grid']['orders']))unset($params['Grid']['orders']['status']); ?>
